package vn.edu.fpt.seal.modules.participant.service;
import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import vn.edu.fpt.seal.common.enums.RoundParticipantStatus; import vn.edu.fpt.seal.common.exception.ApiException; import vn.edu.fpt.seal.modules.participant.dto.*; import vn.edu.fpt.seal.modules.participant.entity.RoundParticipant; import vn.edu.fpt.seal.modules.participant.mapper.RoundParticipantMapper; import vn.edu.fpt.seal.modules.participant.repository.RoundParticipantRepository; import vn.edu.fpt.seal.modules.round.entity.Round; import vn.edu.fpt.seal.modules.round.repository.RoundRepository; import vn.edu.fpt.seal.modules.team.entity.Team; import vn.edu.fpt.seal.modules.team.repository.TeamRepository; import java.util.UUID;
@Service @RequiredArgsConstructor public class RoundParticipantService{ private final RoundParticipantRepository repo; private final RoundRepository roundRepo; private final TeamRepository teamRepo;
 @Transactional(readOnly=true) public Page<RoundParticipantResponse> list(UUID roundId,UUID teamId,RoundParticipantStatus status,Pageable p){Page<RoundParticipant> page=roundId!=null?repo.findByRoundId(roundId,p):teamId!=null?repo.findByTeamId(teamId,p):status!=null?repo.findByStatus(status,p):repo.findAll(p); return page.map(RoundParticipantMapper::toResponse);} @Transactional(readOnly=true) public RoundParticipantResponse get(UUID id){return RoundParticipantMapper.toResponse(find(id));}
 @Transactional public RoundParticipantResponse add(AddRoundParticipantRequest r){Round round=roundRepo.findById(r.roundId()).orElseThrow(()->ApiException.notFound("Round not found: "+r.roundId())); Team team=teamRepo.findById(r.teamId()).orElseThrow(()->ApiException.notFound("Team not found: "+r.teamId())); if(!team.getTrack().getId().equals(round.getTrack().getId())) throw ApiException.badRequest("Team must belong to the same track as round"); if(repo.existsByRoundIdAndTeamId(r.roundId(),r.teamId())) throw ApiException.conflict("Team already participates in this round"); return RoundParticipantMapper.toResponse(repo.save(RoundParticipant.builder().round(round).team(team).status(r.status()==null?RoundParticipantStatus.pending:r.status()).note(trim(r.note())).build()));}
 @Transactional public RoundParticipantResponse update(UUID id,UpdateRoundParticipantRequest r){RoundParticipant p=find(id); if(r.status()!=null)p.setStatus(r.status()); if(r.note()!=null)p.setNote(trim(r.note())); return RoundParticipantMapper.toResponse(p);} @Transactional public void delete(UUID id){repo.delete(find(id));} private RoundParticipant find(UUID id){return repo.findWithRelationsById(id).orElseThrow(()->ApiException.notFound("Round participant not found: "+id));} private String trim(String s){return s==null?null:s.trim();}}
